import sys
from collections import Counter

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    q = int(data[1])

    coins = list(map(int, data[2:2+n]))
    queries = list(map(int, data[2+n:]))

    # Count the occurrences of each power of 2 in the coins
    coin_counts = Counter()
    for coin in coins:
        coin_counts[coin] += 1

    results = []

    for query in queries:
        if query == 0:
            results.append(0)
            continue

        target = query
        num_coins = 0

        # Check if we can form the target using the available coins
        for power in range(32, -1, -1):
            bit_value = 1 << power
            if bit_value > target:
                continue
            if target & bit_value:
                if coin_counts[bit_value] > 0:
                    coin_counts[bit_value] -= 1
                    num_coins += 1
                    target -= bit_value
                else:
                    results.append(-1)
                    break
        else:
            results.append(num_coins)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
